const body = $json.body ?? $json ?? {};
const claims = $json.jwtPayload ?? {};
const userId = claims.sub || body.user_id || '00000000-0000-4000-8000-000000000000';
return [{
  json: {
    session_id: body.session_id || '00000000-0000-4000-8000-000000000000',
    user_id: userId,
    focus: body.focus || 'High-converting client acquisition offer',
    delivery: body.delivery || 'Done-With-You / Agency',
    paid_traffic: body.paid_traffic || 'Organic & Paid Traffic',
    timeline: body.timeline || '6-12 weeks',
    pricing: body.pricing || '$3,000 - $10,000',
    blueprint: body.blueprint || null,
    asset_context: String(body.asset_context || ''),
    selected_sections: Array.isArray(body.selected_sections) ? body.selected_sections : []
  }
}];

