parameters.jsCode:
const source = $input.first().json;
const raw = source.output ?? source.text ?? source.response?.text ?? source;
let offer = raw;
if (typeof raw === 'string') {
  try {
    offer = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
  } catch {
    offer = {
      title: 'High-Impact Strategic Growth Offer',
      promise: 'Predictable growth and operational efficiency',
      audience: 'Target Business Owners',
      core_angle: 'Leverage and execution speed',
      delivery_model: 'Done-With-You',
      traffic_strategy: 'Inbound & Direct Outreach',
      timeline: '90 Days',
      pricing: '$5,000',
      scope: ['Core Deliverables', 'Implementation Roadmap', 'Support'],
      success_metrics: ['ROI within 60 days', 'Time saved'],
      risk_reversal: 'Milestone satisfaction review'
    };
  }
}
if (offer?.output) offer = offer.output;
const input = $('Verify User and Normalize').first().json;
const loaded = $('Load Buyer Project').first()?.json ?? {};
const buyer = loaded.blueprint ?? loaded.audience_profile ?? input.blueprint ?? { persona_name: 'Target Buyer' };
offer.generated_at = new Date().toISOString();
return [{ json: { ...offer, offer, session_id: input.session_id, user_id: input.user_id, blueprint: { ...buyer, offer } } }];
